Method.Source:
    /// <summary>
    /// Modified fields' validations
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get table args</param>
    [DataEventHandler(tableStr(LogisticsAddressState), DataEventType::ModifiedField)]
    public static void LogisticsAddressState_onModifiedField(Common sender, DataEventArgs e)
    {
        ModifyFieldEventArgs    event = e as DataEventArgs;
        LogisticsAddressState   logisticsAddressState = sender as LogisticsAddressState;
        FieldId                 fieldId = event.parmFieldId();
        ;

        switch(fieldId)
        {
            case fieldNum(LogisticsAddressState, METValidateTobaccoLicence):
                str strTitle = "@MET:METUpdateConfirmation";
                if(logisticsAddressState.METValidateTobaccoLicence == NoYes::Yes)
                {
                    str strMessage = "@MET:METMetcashLicEnableMsg";
                    DialogButton dlgBtn = Box::yesNo(strMessage, DialogButton::Yes, strTitle);
                    logisticsAddressState.METValidateTobaccoLicence = (dlgBtn == DialogButton::Yes) ? NoYes::Yes : NoYes::No;
                }
                else
                {
                    str strMessage = "@MET:METMetcashLicDisableMsg";
                    DialogButton dlgBtn = Box::yesNo(strMessage, DialogButton::Yes, strTitle);
                    logisticsAddressState.METValidateTobaccoLicence = (dlgBtn == DialogButton::Yes) ? NoYes::No : NoYes::Yes;
                }
                break;
        }
    }
